WITH transactions_by_account AS (SELECT account_id, ROUND(AVG(amount), 2) AS avg_amount, COUNT(CASE WHEN txn_type = 'CREDIT' THEN 1 END) AS credit_count FROM transactions WHERE merchant IN ('Grab', 'Lazada', 'Shell') GROUP BY account_id) SELECT a.id, a.opened_date, tba.avg_amount, tba.credit_count FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.credit_count >= 3 ORDER BY opened_date, credit_count DESC
